using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEngine.Rendering;
public static class OpenRPGTorchGeometryV150 {
 [Serializable] public class Request {public string output,prefab_path,prefab_guid;}
 [Serializable] public class Identity {public string guid,file_id,name,type;}
 [Serializable] public class Attribute {public string semantic,format;public int dimension,stream,offset;}
 [Serializable] public class Stream {public int index,stride;public string bytes_base64;}
 [Serializable] public class Submesh {public int index_start,index_count,base_vertex,first_vertex,vertex_count;public string topology;public Bounds bounds;}
 [Serializable] public class Geometry {public Identity identity;public int vertices;public string index_format,index_bytes_base64;public Bounds bounds;public Attribute[] attributes;public Stream[] streams;public Submesh[] submeshes;}
 [Serializable] public class Binding {public string path,role;public Identity mesh;}
 [Serializable] public class Lod {public float screen_relative_height,fade_width;public Identity[] renderers;}
 [Serializable] public class LodSet {public string path;public Vector3 reference_point;public float size;public string fade_mode;public bool animate_cross_fading;public Lod[] lods;}
 [Serializable] public class Report {public string unity_version,prefab_guid;public Geometry[] meshes;public Binding[] bindings;public LodSet[] lod_groups;public bool source_components_unchanged,geometry_exported=true,runtime_converted=false,full_import=false;}
 static Identity Id(UnityEngine.Object o){if(o==null)throw new Exception("Missing native geometry reference");string g;long f;if(!AssetDatabase.TryGetGUIDAndLocalFileIdentifier(o,out g,out f))throw new Exception("No persistent native identity");return new Identity{guid=g,file_id=f.ToString(System.Globalization.CultureInfo.InvariantCulture),name=o.name,type=o.GetType().FullName};}
 static Geometry ExportMesh(Mesh m){using(var owned=Mesh.AcquireReadOnlyMeshData(m)){var d=owned[0];var streams=new List<Stream>();for(int i=0;i<d.vertexBufferCount;i++){streams.Add(new Stream{index=i,stride=d.GetVertexBufferStride(i),bytes_base64=Convert.ToBase64String(d.GetVertexData<byte>(i).ToArray())});}byte[] indices;if(d.indexFormat==IndexFormat.UInt16){var a=d.GetIndexData<ushort>().ToArray();indices=new byte[a.Length*2];Buffer.BlockCopy(a,0,indices,0,indices.Length);}else{var a=d.GetIndexData<uint>().ToArray();indices=new byte[a.Length*4];Buffer.BlockCopy(a,0,indices,0,indices.Length);}var sub=new List<Submesh>();for(int i=0;i<d.subMeshCount;i++){var s=d.GetSubMesh(i);sub.Add(new Submesh{index_start=s.indexStart,index_count=s.indexCount,base_vertex=s.baseVertex,first_vertex=s.firstVertex,vertex_count=s.vertexCount,topology=s.topology.ToString(),bounds=s.bounds});}return new Geometry{identity=Id(m),vertices=d.vertexCount,index_format=d.indexFormat.ToString(),index_bytes_base64=Convert.ToBase64String(indices),bounds=m.bounds,attributes=m.GetVertexAttributes().Select(a=>new Attribute{semantic=a.attribute.ToString(),format=a.format.ToString(),dimension=a.dimension,stream=a.stream,offset=m.GetVertexAttributeOffset(a.attribute)}).ToArray(),streams=streams.ToArray(),submeshes=sub.ToArray()};}}
 static void Walk(Transform t,string path,List<Binding> bindings,Dictionary<string,Mesh> meshes,List<LodSet> lods){Action<Mesh,string> add=(m,role)=>{var id=Id(m);meshes[id.guid+":"+id.file_id]=m;bindings.Add(new Binding{path=path,role=role,mesh=id});};var filter=t.GetComponent<MeshFilter>();if(filter!=null)add(filter.sharedMesh,"mesh_filter");var collider=t.GetComponent<MeshCollider>();if(collider!=null)add(collider.sharedMesh,"mesh_collider");var group=t.GetComponent<LODGroup>();if(group!=null)lods.Add(new LodSet{path=path,reference_point=group.localReferencePoint,size=group.size,fade_mode=group.fadeMode.ToString(),animate_cross_fading=group.animateCrossFading,lods=group.GetLODs().Select(l=>new Lod{screen_relative_height=l.screenRelativeTransitionHeight,fade_width=l.fadeTransitionWidth,renderers=l.renderers.Select(Id).ToArray()}).ToArray()});for(int i=0;i<t.childCount;i++)Walk(t.GetChild(i),path+"/"+i,bindings,meshes,lods);}
 public static void Export(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"--openrpg-manifest");if(i<0)throw new Exception("Manifest absent");var r=JsonUtility.FromJson<Request>(File.ReadAllText(args[i+1]));if(File.Exists(r.output))throw new Exception("Receipt already exists");var p=AssetDatabase.LoadAssetAtPath<GameObject>(r.prefab_path);if(p==null||Id(p).guid!=r.prefab_guid)throw new Exception("Wrong private prefab");var components=p.GetComponentsInChildren<Component>(true);if(components.Any(c=>c==null))throw new Exception("Missing component");var before=components.Select(c=>EditorJsonUtility.ToJson(c,true)).ToArray();var bindings=new List<Binding>();var meshes=new Dictionary<string,Mesh>();var lods=new List<LodSet>();Walk(p.transform,"root",bindings,meshes,lods);if(bindings.Count(b=>b.role=="mesh_filter")!=4||bindings.Count(b=>b.role=="mesh_collider")!=1||lods.Count!=1)throw new Exception("Geometry hierarchy mismatch");var exported=meshes.OrderBy(k=>k.Key).Select(k=>ExportMesh(k.Value)).ToArray();if(!before.SequenceEqual(components.Select(c=>EditorJsonUtility.ToJson(c,true))))throw new Exception("Source components changed");File.WriteAllText(r.output,JsonUtility.ToJson(new Report{unity_version=Application.unityVersion,prefab_guid=r.prefab_guid,meshes=exported,bindings=bindings.ToArray(),lod_groups=lods.ToArray(),source_components_unchanged=true},true));}
}
